//! xAI model catalog ported from Pi's `packages/ai/src/providers/xai.models.ts`.
//!
//! Pi marks this catalog as generated by `scripts/generate-models.ts`; this Rust port
//! preserves the generated entries as checked in for this port row.

/// Pricing metadata for an xAI model.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct XaiModelCost {
    /// Input token price in Pi's model catalog units.
    pub input: f64,
    /// Output token price in Pi's model catalog units.
    pub output: f64,
    /// Cache-read token price in Pi's model catalog units.
    pub cache_read: f64,
    /// Cache-write token price in Pi's model catalog units.
    pub cache_write: f64,
}

/// OpenAI-compatible feature flags for an xAI model.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct XaiModelCompat {
    /// Whether the model supports the OpenAI store option.
    pub supports_store: bool,
    /// Whether the model supports the developer role.
    pub supports_developer_role: bool,
    /// Whether the model supports the reasoning-effort parameter.
    pub supports_reasoning_effort: bool,
}

/// One xAI model entry from Pi's generated model catalog.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct XaiModel {
    /// Model id and catalog key.
    pub id: &'static str,
    /// Human-readable model name.
    pub name: &'static str,
    /// API implementation id.
    pub api: &'static str,
    /// Provider id.
    pub provider: &'static str,
    /// Base API URL.
    pub base_url: &'static str,
    /// OpenAI-compatible feature flags.
    pub compat: XaiModelCompat,
    /// Whether the model supports reasoning.
    pub reasoning: bool,
    /// Supported input modalities.
    pub input: &'static [&'static str],
    /// Model cost metadata.
    pub cost: XaiModelCost,
    /// Context window in tokens.
    pub context_window: u32,
    /// Maximum output tokens.
    pub max_tokens: u32,
}

const TEXT: &[&str] = &["text"];
const TEXT_IMAGE: &[&str] = &["text", "image"];
const API: &str = "openai-completions";
const PROVIDER: &str = "xai";
const BASE_URL: &str = "https://api.x.ai/v1";
const COMPAT: XaiModelCompat = XaiModelCompat {
    supports_store: false,
    supports_developer_role: false,
    supports_reasoning_effort: false,
};

