#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn preserves_xai_catalog_metadata() {
        assert_eq!(XAI_MODELS.len(), 7);
        assert_eq!(XAI_MODELS[0].id, "grok-3");
        assert_eq!(XAI_MODELS[0].cost.cache_read, 0.75);
        assert!(!XAI_MODELS[2].reasoning);
        assert!(XAI_MODELS[3].reasoning);
        assert_eq!(XAI_MODELS[4].context_window, 1_000_000);
        assert_eq!(XAI_MODELS[5].max_tokens, 256_000);
        assert_eq!(XAI_MODELS[6].input, TEXT);
        assert_eq!(XAI_MODELS[6].compat, COMPAT);
    }
}
